-- Update sum ticket on bettrans from bettransRnG/LC
DECLARE @bettransDetail TABLE (transid BIGINT, refno BIGINT, epositiontaking SMALLMONEY)

	-- RnG
	INSERT INTO @bettransDetail (transid, refno, epositiontaking)
	SELECT transid, refno, epositiontaking
	FROM dbo.bettransRnG WITH (NOLOCK)
	WHERE transid IN (
		104336288310,104336288042,104336287471,104336287096,104336285897,104336285676,104336285632,104336285805,104336287345,104336284591,104336285437
		,104336288284,104336287221,104336288148,104336288327,104336288212,104336286637,104336287218,104336288309
		)

	INSERT INTO @bettransDetail (transid, refno, epositiontaking)
	SELECT b.transid, b.refno, b.epositiontaking
	FROM dbo.bettransRnG b WITH (NOLOCK)
		LEFT JOIN @bettransDetail bt ON b.transid = bt.transid
	WHERE bt.transid IS NULL
		AND b.RefNo IN (SELECT t.refno FROM @bettransDetail t)

	-- LC
	INSERT INTO @bettransDetail (transid, refno, epositiontaking)
	SELECT transid, refno, epositiontaking
	FROM dbo.bettransLC WITH (NOLOCK)
	WHERE transid IN (
		519153632,519153789,519153761,519153742,519153269,519153133,519153152,519153094,519152842,519152773,519153735,519153499,519153340,519153239,519152891
		,519153095,519152890,519153576,519153771,519153780,519153574,519153298,519153342,519153195,519153237,519152988,519152981,519152978,519152896,519152888
		,519152887,519152778,519152834,519153630,519153802,519153502,519152906,519152827,519152885,519152775,519153010,519152780,519153134,519152986,519152886
		,519152979,519153608,519152821,519152911,519153207,519153397,519153503,519153804,519153102,519153404,519153498,519153667,519152916,519153848,519153132
		,519153262,519153020,519153775,519153692,519153501,519153601,519152915,519152822,519153762,519153299,519153411,519153137,519153096,519152958,519152940
		,519152843,519153655
		)

	INSERT INTO @bettransDetail (transid, refno, epositiontaking)
	SELECT b.transid, b.refno, b.epositiontaking
	FROM dbo.bettransLC b WITH (NOLOCK)
		LEFT JOIN @bettransDetail bt ON b.transid = bt.transid
	WHERE bt.transid IS NULL
		AND b.RefNo IN (SELECT t.refno FROM @bettransDetail t)

	UPDATE b
	SET b.epositiontaking = t.epositiontaking
	FROM dbo.bettrans b
		INNER JOIN (
			SELECT refno, AVG(epositiontaking) AS epositiontaking
			FROM @bettransDetail
			GROUP BY refno
		) t ON b.transid = t.refno